// Synthetic-only preparation. Replace with an approved channel adapter at deployment time.
// Business profile: one file of approved facts per client (services, prices, hours, policies, handover).
const profile = {
  business: {
    name: 'Sunrise Dental Clinic (DEMO)',
    type: 'clinic',
    languages: ['English', 'Hinglish'],
    hours: 'Mon-Sat, 9am-7pm IST',
    location: 'MG Road, Demo City; approved map link on file',
    handover_contact: '+919000000000',
    emergency_note: 'For emergencies call +919000000001'
  },
  services: [
    { name: 'Consultation', price: 'Rs 500', duration_min: 30, bookable: true },
    { name: 'Cleaning', price: 'Rs 1200', duration_min: 45, bookable: true },
    { name: 'Braces consult', price: 'On request', duration_min: 60, bookable: false }
  ],
  faqs: [
    { q: 'Do you offer home visits?', a: 'Home visits are not offered; clinic visits only.' }
  ],
  policies: { cancellation: 'Cancel 4 hours before the slot.', payment: 'Pay at the clinic.', refunds: 'Handled by the clinic owner only.' },
  modules: { booking: true, lead_capture: true, order_status: false, payment_link: false },
  never: ['give medical, legal or financial advice', 'promise discounts', 'quote unlisted prices'],
  escalate_on: ['emergency', 'complaint', 'refund', 'asks for a human']
};
const message = {
  name: 'Priya (demo)',
  contact: '+919000000002',
  text: 'Kal ka slot milega kya?',
  consent_status: 'granted',
  channel: 'whatsapp_demo',
  correlation_id: 'DEMO-UR-INTAKE-001'
};
const correlation_id = message.correlation_id || 'DEMO-UNIVERSAL-REPLIER-INTAKE-SAMPLE';
return [{ json: { ...message, profile, correlation_id, _demo: true, _scenario: 'replier-intake' } }];

const d = $input.first().json;
const profile = d.profile || null;
const text = String(d.text || '');
const missing = ['name', 'contact', 'text'].filter((key) => !String(d[key] || '').trim());
const escalationWords = /emergency|urgent|accident|complaint|refund|worst|terrible|unacceptable|speak to|talk to|manager/i;
const adviceWords = /diagnos|prescri|dosage|medicine for|legal advice|tax advice|invest/i;
const sensitive = escalationWords.test(text) || adviceWords.test(text);
const review = missing.length > 0 || sensitive || d.consent_status !== 'granted' || !profile;
return [{ json: { ...d, _validation: { status: review ? 'NEEDS_HUMAN_REVIEW' : 'READY', review_required: review, missing, reason: missing.length ? 'Required message data is missing' : sensitive ? 'Message matches an escalation or advice rule' : d.consent_status !== 'granted' ? 'Consent is not confirmed' : !profile ? 'Business profile not loaded' : 'Message validated against the business profile' } } }];

const d = $input.first().json;
const v = d._validation || { status: 'NEEDS_HUMAN_REVIEW', review_required: true, reason: 'Validation output missing' };
const profile = d.profile || { business: {}, services: [], faqs: [], policies: {}, never: [] };
const text = String(d.text || '');
const intents = [
  ['emergency', /emergency|urgent|accident|severe|bleeding/i],
  ['human_request', /speak to|talk to|human|person|manager|someone/i],
  ['complaint', /complaint|worst|terrible|unacceptable|refund/i],
  ['booking', /slot|appointment|book|available|tomorrow|kal|visit/i],
  ['pricing', /price|fees?|cost|rate|kitna|charges/i],
  ['hours_location', /open|hours|timings?|where|address|location/i],
  ['order_status', /order|delivery|dispatch/i],
  ['quote_request', /quote|estimate|quotation/i],
  ['service_info', /do you (do|offer)|services?|treatment|package/i],
  ['greeting', /^(hi|hello|hey|namaste|good (morning|afternoon|evening))/i]
];
let intent = 'other';
for (const pair of intents) { if (pair[1].test(text)) { intent = pair[0]; break; } }
const escalationIntents = ['emergency', 'complaint', 'human_request', 'other'];
const requiresHuman = v.status === 'NEEDS_HUMAN_REVIEW' || escalationIntents.includes(intent);
let reply;
if (requiresHuman) {
  reply = intent === 'emergency'
    ? 'Draft only: Share the profile emergency note (' + (profile.business.emergency_note || 'on file') + ') and alert the handover contact.'
    : 'Draft only: Acknowledge briefly and route to the team. Do not invent facts or promises.';
} else if (intent === 'booking') {
  reply = 'Draft only: Offer slots returned by the approved scheduling source only; confirm after booking.';
} else if (intent === 'pricing') {
  const listed = (profile.services || []).filter((s) => s.price && s.price !== 'On request').map((s) => s.name + ': ' + s.price).join('; ');
  reply = 'Draft only: Share listed prices only (' + (listed || 'none listed') + '). Say the team will confirm anything unlisted.';
} else if (intent === 'hours_location') {
  reply = 'Draft only: Hours on file: ' + (profile.business.hours || 'unlisted') + '. Location on file: ' + (profile.business.location || 'unlisted') + '.';
} else if (intent === 'service_info') {
  reply = 'Draft only: Answer from the approved services and FAQ list only.';
} else if (intent === 'quote_request') {
  reply = 'Draft only: Collect requirement details into the lead sheet and alert the team.';
} else {
  reply = 'Draft only: Greet and show what the replier can help with, using profile facts only.';
}
const correlation_id = d.correlation_id || 'DEMO-UNKNOWN';
const audit = { workflow: 'replier-intake', action: 'draft_only', record_id: d.contact || 'sample', correlation_id: correlation_id };
return [{ json: { ...d, status: requiresHuman ? 'NEEDS_HUMAN_REVIEW' : 'DRAFT_ONLY', review_required: requiresHuman, intent: intent, reply: reply, needs_human: requiresHuman, reason: v.reason, action_draft: { reply: reply, owner: requiresHuman ? 'human-review' : 'replier' }, audit } }];
